👍 

this is restoring compatibility with the 1.36 WantsAuthorizer signature

```diff
git diff upstream/release-1.36 HEAD -- staging/src/k8s.io/apiserver/pkg/admission/initializer/initializer.go
diff --git a/staging/src/k8s.io/apiserver/pkg/admission/initializer/initializer.go b/staging/src/k8s.io/apiserver/pkg/admission/initializer/initializer.go
index b7880296896..a1d7ace4a5f 100644
--- a/staging/src/k8s.io/apiserver/pkg/admission/initializer/initializer.go
+++ b/staging/src/k8s.io/apiserver/pkg/admission/initializer/initializer.go
@@ -91,6 +91,9 @@ func (i pluginInitializer) Initialize(plugin admission.Interface) {
                wants.SetExternalKubeInformerFactory(i.externalInformers)
        }

+       if wants, ok := plugin.(WantsUnconditionalAuthorizer); ok {
+               wants.SetUnconditionalAuthorizer(i.authorizer)
+       }
        if wants, ok := plugin.(WantsAuthorizer); ok {
                wants.SetAuthorizer(i.authorizer)
        }
```
